// Legal Dictionary Terms Database
// 250+ essential legal terms for Indian lawyers

class LegalTerm {
  final String term;
  final String category;
  final String meaning;
  final String usage;
  final String section;
  const LegalTerm({required this.term, required this.category, required this.meaning, this.usage = '', this.section = ''});
}

const List<LegalTerm> legalTermsData = [
  // ═══ LATIN MAXIMS ═══
  LegalTerm(term: 'Audi Alteram Partem', category: 'Latin', meaning: 'Hear the other side. No person should be condemned unheard.', usage: 'A fundamental rule of natural justice — courts must give both parties a chance to be heard before passing orders.', section: 'Article 14, 21 Constitution'),
  LegalTerm(term: 'Res Judicata', category: 'Latin', meaning: 'A matter already judged. A decided case cannot be re-litigated between the same parties on the same issue.', usage: 'The defendant raised a plea of res judicata under Section 11 CPC, arguing this issue was already decided in a prior suit.', section: 'Section 11 CPC'),
  LegalTerm(term: 'Res Ipsa Loquitur', category: 'Latin', meaning: 'The thing speaks for itself. Negligence is inferred from the very nature of the accident.', usage: 'When a surgical sponge is left inside a patient, res ipsa loquitur applies — the negligence is self-evident.'),
  LegalTerm(term: 'Actus Reus', category: 'Latin', meaning: 'Guilty act. The physical element of a crime.', usage: 'For a conviction of murder, prosecution must prove both actus reus (the killing) and mens rea (the intention).', section: 'BNS General Principles'),
  LegalTerm(term: 'Mens Rea', category: 'Latin', meaning: 'Guilty mind. The mental element or criminal intent required for a crime.', usage: 'The accused had no mens rea since the death was purely accidental, not intentional or reckless.', section: 'BNS General Principles'),
  LegalTerm(term: 'Habeas Corpus', category: 'Latin', meaning: 'Produce the body. A writ directing a person detaining another to produce them before the court.', usage: 'A habeas corpus petition was filed in High Court challenging the illegal detention of the accused beyond 24 hours.', section: 'Article 32, 226 Constitution'),
  LegalTerm(term: 'Mandamus', category: 'Latin', meaning: 'We command. A writ ordering a public authority to perform its duty.', usage: 'Mandamus was issued directing the municipality to repair the road, being a public duty they were bound to perform.', section: 'Article 32, 226 Constitution'),
  LegalTerm(term: 'Certiorari', category: 'Latin', meaning: 'To be certified. A writ by a higher court to review and quash the decision of a lower court or tribunal.', usage: 'The High Court issued certiorari quashing the tribunal order as it was passed without jurisdiction.', section: 'Article 226, 227 Constitution'),
  LegalTerm(term: 'Quo Warranto', category: 'Latin', meaning: 'By what authority? A writ challenging the legal authority of a person holding public office.', usage: 'Quo warranto was filed questioning the appointment of the Municipal Commissioner without following statutory procedure.', section: 'Article 226 Constitution'),
  LegalTerm(term: 'Prohibition', category: 'Latin', meaning: 'A writ issued by a higher court preventing a lower court from exceeding its jurisdiction.', usage: 'Writ of prohibition was issued to prevent the civil court from trying a matter exclusively within revenue court jurisdiction.', section: 'Article 226 Constitution'),
  LegalTerm(term: 'Caveat Emptor', category: 'Latin', meaning: 'Let the buyer beware. The buyer takes the risk regarding quality of the goods purchased.', usage: 'Under caveat emptor, the buyer who failed to inspect the property before purchase cannot later claim hidden defects.', section: 'Section 16 Sale of Goods Act'),
  LegalTerm(term: 'Damnum Sine Injuria', category: 'Latin', meaning: 'Damage without legal injury. Loss suffered without violation of any legal right — not actionable.', usage: 'Opening a competing shop causing loss to a rival is damnum sine injuria — no legal right is infringed.'),
  LegalTerm(term: 'Injuria Sine Damno', category: 'Latin', meaning: 'Legal injury without actual damage. Violation of a legal right even without loss — actionable.', usage: 'Refusing a registered voter entry to the polling booth is injuria sine damno — legal right violated even if no monetary damage.'),
  LegalTerm(term: 'Volenti Non Fit Injuria', category: 'Latin', meaning: 'A willing person suffers no injury. Consent to risk negates a claim for injury.', usage: 'A boxer cannot sue for injuries sustained during a match — volenti non fit injuria applies.'),
  LegalTerm(term: 'Nemo Debet Bis Vexari', category: 'Latin', meaning: 'No person should be tried or punished twice for the same offence. Double jeopardy.', usage: 'The accused was acquitted once; prosecuting again on the same facts violates the principle of double jeopardy.', section: 'Article 20(2) Constitution / Sec 337 BNSS'),
  LegalTerm(term: 'Ubi Jus Ibi Remedium', category: 'Latin', meaning: 'Where there is a right, there is a remedy.', usage: 'The court cannot refuse relief merely because no specific remedy is mentioned in statute — ubi jus ibi remedium applies.'),
  LegalTerm(term: 'Ignorantia Juris Non Excusat', category: 'Latin', meaning: 'Ignorance of law is no excuse. Every person is presumed to know the law.', usage: 'The accused cannot escape liability by claiming he did not know that carrying a knife in public was illegal.'),
  LegalTerm(term: 'De Facto', category: 'Latin', meaning: 'In fact. Existing in reality, whether legally recognized or not.', usage: 'He was the de facto guardian of the minor, though no formal guardianship order was passed.'),
  LegalTerm(term: 'De Jure', category: 'Latin', meaning: 'By law. Legally recognized, whether or not it exists in practice.', usage: 'She is the de jure owner per the title deed, though the property is in de facto possession of the tenant.'),
  LegalTerm(term: 'Prima Facie', category: 'Latin', meaning: 'At first sight. Evidence sufficient to establish a fact unless rebutted.', usage: 'The prosecution established a prima facie case for framing charges against the accused.', section: 'Sec 232 BNSS (Charge)'),
  LegalTerm(term: 'Obiter Dictum', category: 'Latin', meaning: 'Said in passing. Observations by a judge not essential to the decision — not binding precedent.', usage: 'The Supreme Court\'s remark on social media regulation was merely obiter dictum, not the ratio decidendi.'),
  LegalTerm(term: 'Ratio Decidendi', category: 'Latin', meaning: 'The reason for deciding. The legal principle on which a judgment is based — binding as precedent.', usage: 'The ratio decidendi of Maneka Gandhi v. Union of India is that Article 21 includes the right to live with dignity.'),
  LegalTerm(term: 'Stare Decisis', category: 'Latin', meaning: 'Stand by what has been decided. Courts should follow precedent.', usage: 'Following the doctrine of stare decisis, the High Court is bound by Supreme Court judgments on the same point of law.'),
  LegalTerm(term: 'Locus Standi', category: 'Latin', meaning: 'Right to stand. The legal capacity to bring a case before the court.', usage: 'A stranger to a contract has no locus standi to challenge its terms in court.'),
  LegalTerm(term: 'Inter Alia', category: 'Latin', meaning: 'Among other things.', usage: 'The petition raised, inter alia, the violation of Article 14 and Article 21 of the Constitution.'),
  LegalTerm(term: 'Mala Fide', category: 'Latin', meaning: 'In bad faith. Done with dishonest or fraudulent intent.', usage: 'The transfer order was passed mala fide, as a punishment for filing an RTI application.'),
  LegalTerm(term: 'Bona Fide', category: 'Latin', meaning: 'In good faith. Genuine and honest.', usage: 'The landlord requires the premises for bona fide personal use under the Rent Control Act.'),
  LegalTerm(term: 'Ultra Vires', category: 'Latin', meaning: 'Beyond the powers. An act done beyond the legal authority of the person or body doing it.', usage: 'The municipal notification was struck down as ultra vires the parent statute.'),
  LegalTerm(term: 'Intra Vires', category: 'Latin', meaning: 'Within the powers. An act done within legal authority.', usage: 'The regulation was held intra vires as Parliament had expressly delegated this power.'),
  LegalTerm(term: 'Sub Judice', category: 'Latin', meaning: 'Under judicial consideration. A case currently being heard.', usage: 'The matter is sub judice before the Supreme Court; no comment should be made that prejudices the case.', section: 'Sec 3 Contempt of Courts Act'),
  LegalTerm(term: 'Suo Motu', category: 'Latin', meaning: 'On its own motion. When a court takes action without a petition or complaint.', usage: 'The High Court took suo motu cognizance of the pollution in the river based on newspaper reports.'),
  LegalTerm(term: 'Ad Interim', category: 'Latin', meaning: 'In the meantime. A temporary order pending final hearing.', usage: 'The court granted ad interim injunction restraining the defendant from alienating the property.'),
  LegalTerm(term: 'Ex Parte', category: 'Latin', meaning: 'From one side only. A hearing or order made without the other party being present.', usage: 'An ex parte decree was passed as the defendant failed to appear despite due service of summons.', section: 'Order 9 Rule 6 CPC'),
  LegalTerm(term: 'Ad Hoc', category: 'Latin', meaning: 'For this purpose. Temporary or formed for a specific task.', usage: 'An ad hoc committee was constituted to investigate the allegations against the officer.'),
  LegalTerm(term: 'Amicus Curiae', category: 'Latin', meaning: 'Friend of the court. A person appointed by the court to assist with legal arguments in public interest cases.', usage: 'The Supreme Court appointed a senior advocate as amicus curiae to assist in the PIL.'),
  LegalTerm(term: 'Pro Bono', category: 'Latin', meaning: 'For the public good. Legal services rendered free of charge.', usage: 'The advocate appeared pro bono for the indigent accused who could not afford legal representation.'),
  LegalTerm(term: 'Ipso Facto', category: 'Latin', meaning: 'By the fact itself. As an inevitable consequence.', usage: 'Conviction under BNS Section 103 ipso facto disqualifies a person from holding public office.'),
  LegalTerm(term: 'Mutatis Mutandis', category: 'Latin', meaning: 'With necessary changes. Applied with appropriate modifications.', usage: 'The rules applicable to civil suits shall apply mutatis mutandis to appeals.'),
  LegalTerm(term: 'In Personam', category: 'Latin', meaning: 'Against a person. A legal action directed at a specific individual.', usage: 'A decree for specific performance is in personam — it directs the specific defendant to perform.'),
  LegalTerm(term: 'In Rem', category: 'Latin', meaning: 'Against a thing. A legal action directed against property, binding on the whole world.', usage: 'A probate decree is in rem — it establishes the validity of a will against all persons.'),
  LegalTerm(term: 'Vis Major', category: 'Latin', meaning: 'Superior force. An irresistible natural event (Act of God) excusing performance of obligation.', usage: 'The defendant pleaded vis major when floods destroyed the goods in transit, preventing delivery.'),
  LegalTerm(term: 'Doli Incapax', category: 'Latin', meaning: 'Incapable of crime. A child below 7 years cannot commit an offence.', usage: 'A child of 5 is doli incapax and cannot be prosecuted under criminal law.', section: 'BNS Section 17'),
  LegalTerm(term: 'Nemo Judex In Causa Sua', category: 'Latin', meaning: 'No one should be a judge in their own cause. Rule against bias.', usage: 'The judge recused himself as his relative was a party — nemo judex in causa sua.'),
  LegalTerm(term: 'Ejusdem Generis', category: 'Latin', meaning: 'Of the same kind. General words following specific words are limited to the same category.', usage: 'In "cars, buses, trucks, and other vehicles," other vehicles means motor vehicles, not bicycles.'),
  LegalTerm(term: 'Pari Materia', category: 'Latin', meaning: 'Of the same matter. Statutes dealing with the same subject should be interpreted together.', usage: 'BNS and BNSS, being in pari materia, must be read harmoniously.'),
  LegalTerm(term: 'Pro Rata', category: 'Latin', meaning: 'In proportion. Distributed proportionally.', usage: 'The decree amount shall be distributed pro rata among the creditors.'),
  LegalTerm(term: 'Status Quo', category: 'Latin', meaning: 'The existing state of affairs.', usage: 'The court ordered status quo, directing both parties to maintain the current possession of the property.'),

  // ═══ LEGAL ENGLISH / GENERAL ═══
  LegalTerm(term: 'Injunction', category: 'Legal English', meaning: 'A court order preventing a party from doing (or requiring them to do) something.', usage: 'A temporary injunction was granted preventing the defendant from constructing on the disputed land.', section: 'Order 39 CPC / Sec 36-42 Specific Relief Act'),
  LegalTerm(term: 'Affidavit', category: 'Legal English', meaning: 'A written statement confirmed by oath or affirmation, used as evidence in court.', usage: 'The petitioner filed an affidavit stating all material facts in support of the bail application.', section: 'Order 19 CPC'),
  LegalTerm(term: 'Decree', category: 'Legal English', meaning: 'The formal expression of an adjudication by a court conclusively determining the rights of parties.', usage: 'The trial court passed a decree for possession in favour of the plaintiff.', section: 'Sec 2(2) CPC'),
  LegalTerm(term: 'Judgment', category: 'Legal English', meaning: 'The statement given by a judge on the grounds of a decree or order.', usage: 'The judgment of the Supreme Court was delivered in open court and reported at AIR 2024 SC 445.', section: 'Sec 2(9) CPC'),
  LegalTerm(term: 'Order', category: 'Legal English', meaning: 'The formal expression of a decision of a court that is not a decree.', usage: 'The court passed an order rejecting the application for adjournment.', section: 'Sec 2(14) CPC'),
  LegalTerm(term: 'Plaint', category: 'Legal English', meaning: 'The written statement of claim filed by the plaintiff to initiate a civil suit.', usage: 'The plaint was rejected under Order 7 Rule 11 CPC as it did not disclose a cause of action.', section: 'Order 7 CPC'),
  LegalTerm(term: 'Written Statement', category: 'Legal English', meaning: 'The defendant\'s written reply to the plaint in a civil suit.', usage: 'The defendant filed written statement within 30 days denying all allegations in the plaint.', section: 'Order 8 CPC'),
  LegalTerm(term: 'Caveat', category: 'Legal English', meaning: 'A notice filed by a person to ensure they are heard before any order is passed against them.', usage: 'A caveat was lodged to prevent the court from granting ex parte relief.', section: 'Sec 148A CPC'),
  LegalTerm(term: 'Bail', category: 'Legal English', meaning: 'Temporary release of an accused person awaiting trial, on condition of security.', usage: 'The accused was released on bail of ₹50,000 with two sureties.', section: 'Sec 478-489 BNSS'),
  LegalTerm(term: 'Anticipatory Bail', category: 'Legal English', meaning: 'Pre-arrest bail granted to a person apprehending arrest.', usage: 'The accused filed for anticipatory bail fearing arrest in a dowry harassment case.', section: 'Sec 482 BNSS'),
  LegalTerm(term: 'FIR', category: 'Legal English', meaning: 'First Information Report. The first complaint registered at a police station regarding a cognizable offence.', usage: 'An FIR was registered under BNS Section 303 for theft at the local police station.', section: 'Sec 173 BNSS'),
  LegalTerm(term: 'Chargesheet', category: 'Legal English', meaning: 'A formal document filed by police before the court after completing investigation, containing evidence against the accused.', usage: 'Police filed chargesheet within 90 days listing 12 witnesses and documentary evidence.', section: 'Sec 193 BNSS'),
  LegalTerm(term: 'Cognizable Offence', category: 'Criminal', meaning: 'An offence in which police can arrest without warrant and investigate without court permission.', usage: 'Murder is a cognizable offence — police must register FIR and may arrest without a warrant.', section: 'Sec 2(1)(c) BNSS'),
  LegalTerm(term: 'Non-Cognizable Offence', category: 'Criminal', meaning: 'An offence in which police cannot arrest without warrant and cannot investigate without court permission.', usage: 'Simple assault is a non-cognizable offence. A private complaint must be filed before the Magistrate.', section: 'Sec 2(1)(l) BNSS'),
  LegalTerm(term: 'Bailable Offence', category: 'Criminal', meaning: 'An offence where the accused has a right to be released on bail.', usage: 'Cheating is a bailable offence; the accused is entitled to bail as of right.'),
  LegalTerm(term: 'Summons', category: 'Legal English', meaning: 'A judicial order directing a person to appear before the court at a specified time.', usage: 'The court issued summons to the defendant to appear on the next date of hearing.', section: 'Order 5 CPC / Sec 64 BNSS'),
  LegalTerm(term: 'Warrant', category: 'Legal English', meaning: 'A written order of a court authorizing arrest, search, or other actions.', usage: 'A non-bailable warrant was issued against the absconding accused.', section: 'Sec 73-79 BNSS'),
  LegalTerm(term: 'Adjournment', category: 'Legal English', meaning: 'Postponement of a court hearing to a future date.', usage: 'The case was adjourned to 15th March due to the advocate\'s absence.'),
  LegalTerm(term: 'Acquittal', category: 'Legal English', meaning: 'A judgment that the accused is not guilty of the charges.', usage: 'The court acquitted the accused giving benefit of doubt, as circumstantial evidence was incomplete.'),
  LegalTerm(term: 'Conviction', category: 'Legal English', meaning: 'A formal declaration by the court that the accused is guilty.', usage: 'The accused was convicted under BNS Section 103(1) and sentenced to life imprisonment.'),
  LegalTerm(term: 'Appeal', category: 'Legal English', meaning: 'An application to a higher court to review and change the decision of a lower court.', usage: 'The defendant filed a first appeal in the High Court against the trial court decree.', section: 'Sec 96 CPC / Sec 399 BNSS'),
  LegalTerm(term: 'Revision', category: 'Legal English', meaning: 'Supervisory jurisdiction of a higher court to correct errors of jurisdiction by lower courts.', usage: 'A revision petition was filed under Sec 115 CPC before the High Court.', section: 'Sec 115 CPC / Sec 442 BNSS'),
  LegalTerm(term: 'Writ Petition', category: 'Legal English', meaning: 'A petition invoking the constitutional jurisdiction of High Court or Supreme Court for enforcement of rights.', usage: 'A writ petition under Article 226 was filed challenging the government order as unconstitutional.', section: 'Article 32, 226 Constitution'),
  LegalTerm(term: 'PIL (Public Interest Litigation)', category: 'Legal English', meaning: 'A case filed for the protection of public interest by any citizen, not just the aggrieved party.', usage: 'A PIL was filed seeking direction to the government to provide clean drinking water to the village.'),
  LegalTerm(term: 'Contempt of Court', category: 'Legal English', meaning: 'Willful disobedience of a court order, or conduct that undermines the authority of the judiciary.', usage: 'Contempt proceedings were initiated for non-compliance of the injunction order.', section: 'Contempt of Courts Act, 1971'),
  LegalTerm(term: 'Stay Order', category: 'Legal English', meaning: 'A court order suspending proceedings or the enforcement of a judgment.', usage: 'The High Court granted a stay on the demolition order for four weeks.'),
  LegalTerm(term: 'Specific Performance', category: 'Legal English', meaning: 'A court order directing a party to perform their contractual obligations.', usage: 'The buyer filed a suit for specific performance compelling the seller to execute the sale deed.', section: 'Sec 12-16 Specific Relief Act'),
  LegalTerm(term: 'Limitation', category: 'Legal English', meaning: 'The time period within which a legal action must be filed. After this period, the right to sue expires.', usage: 'The suit was dismissed as barred by limitation since it was filed after the 3-year period.', section: 'Limitation Act, 1963'),
  LegalTerm(term: 'Cause of Action', category: 'Legal English', meaning: 'The set of facts that gives a person the right to judicial relief.', usage: 'The plaint was rejected as it failed to disclose any cause of action against the defendant.', section: 'Order 7 Rule 11 CPC'),
  LegalTerm(term: 'Lien', category: 'Property', meaning: 'The right to retain possession of another\'s property until a debt owed by the owner is discharged.', usage: 'The banker exercised his general lien over the securities deposited by the customer.', section: 'Sec 170-171 Indian Contract Act'),
  LegalTerm(term: 'Mortgage', category: 'Property', meaning: 'Transfer of an interest in immovable property as security for a loan.', usage: 'The borrower created an equitable mortgage by depositing title deeds with the bank.', section: 'Sec 58 Transfer of Property Act'),
  LegalTerm(term: 'Easement', category: 'Property', meaning: 'A right to use another person\'s land for a specific purpose (e.g., right of way).', usage: 'The plaintiff claimed easementary right of way over the defendant\'s property by long usage.', section: 'Indian Easements Act, 1882'),
  LegalTerm(term: 'Encumbrance', category: 'Property', meaning: 'A claim or liability attached to property, such as a mortgage or lien.', usage: 'The EC (Encumbrance Certificate) showed no encumbrance on the property for the last 30 years.'),
  LegalTerm(term: 'Title', category: 'Property', meaning: 'Legal ownership rights over property.', usage: 'The plaintiff proved his title by producing the registered sale deed and revenue records.'),
  LegalTerm(term: 'Partition', category: 'Property', meaning: 'Division of jointly owned property among co-owners.', usage: 'A suit for partition was filed seeking division of ancestral property among all legal heirs.', section: 'Sec 4 Partition Act'),
  LegalTerm(term: 'Adverse Possession', category: 'Property', meaning: 'Acquiring ownership rights over property by continuous, open, and hostile possession for the statutory period.', usage: 'The plaintiff claimed title by adverse possession after 12 years of uninterrupted, hostile possession.', section: 'Article 65 Limitation Act'),
  LegalTerm(term: 'Estoppel', category: 'Legal English', meaning: 'A principle preventing a person from going back on their own representation when another has relied on it.', usage: 'The landlord is estopped from denying the tenancy after accepting rent for 5 years.', section: 'Sec 115 Indian Evidence Act'),
  LegalTerm(term: 'Promissory Estoppel', category: 'Legal English', meaning: 'A party is bound by their promise when the other party has acted to their detriment relying on it.', usage: 'The government cannot withdraw the tax exemption after the company set up the factory relying on the promise.'),
  LegalTerm(term: 'Waiver', category: 'Legal English', meaning: 'Voluntary relinquishment of a known right.', usage: 'By accepting defective goods without objection, the buyer waived the right to reject.'),
  LegalTerm(term: 'Quash', category: 'Legal English', meaning: 'To set aside or declare invalid a court order, FIR, or proceeding.', usage: 'The FIR was quashed by the High Court under Section 528 BNSS as no offence was made out.', section: 'Sec 528 BNSS'),
  LegalTerm(term: 'Remand', category: 'Legal English', meaning: 'Sending a case back to a lower court for fresh trial, or sending an accused to custody.', usage: 'The appeal court remanded the matter for retrial as material evidence was not considered.'),
  LegalTerm(term: 'Compounding', category: 'Criminal', meaning: 'Settlement of a criminal case between the complainant and accused with court permission.', usage: 'The complainant agreed to compound the case of hurt under BNS Sec 115(2) upon receiving compensation.', section: 'Sec 359 BNSS'),
  LegalTerm(term: 'Bail Bond', category: 'Criminal', meaning: 'A written undertaking by the accused (with sureties) to appear before court and comply with conditions.', usage: 'The accused executed a bail bond of ₹1,00,000 with two local sureties.', section: 'Sec 478 BNSS'),
  LegalTerm(term: 'Dying Declaration', category: 'Evidence', meaning: 'A statement made by a person who is about to die, regarding the cause or circumstances of their death.', usage: 'The dying declaration recorded by the Magistrate was the sole basis of conviction.', section: 'Sec 26 BSA (Bharatiya Sakshya Adhiniyam)'),
  LegalTerm(term: 'Hearsay', category: 'Evidence', meaning: 'Evidence based on what a witness heard from someone else, not from personal knowledge. Generally inadmissible.', usage: 'The testimony was rejected as hearsay since the witness did not personally see the incident.', section: 'BSA General Principles'),
  LegalTerm(term: 'Circumstantial Evidence', category: 'Evidence', meaning: 'Evidence that relies on inference to connect facts to a conclusion, rather than direct testimony.', usage: 'The chain of circumstantial evidence was complete, pointing only to the guilt of the accused.'),
  LegalTerm(term: 'Corroboration', category: 'Evidence', meaning: 'Supporting evidence that confirms or strengthens existing testimony.', usage: 'The approver\'s testimony requires corroboration on material particulars before conviction.'),
  LegalTerm(term: 'Cross-Examination', category: 'Evidence', meaning: 'Questioning of a witness by the opposing party to test credibility and accuracy.', usage: 'During cross-examination, the prosecution witness contradicted his own statement.', section: 'Sec 145 BSA'),
  LegalTerm(term: 'Examination-in-Chief', category: 'Evidence', meaning: 'Questioning of a witness by the party who called them.', usage: 'In examination-in-chief, the plaintiff narrated the entire transaction leading to the dispute.', section: 'Sec 143 BSA'),
  LegalTerm(term: 'Re-examination', category: 'Evidence', meaning: 'Further questioning by the party who called the witness, after cross-examination, to clarify points.', usage: 'In re-examination, the witness clarified the discrepancy raised during cross-examination.', section: 'Sec 146 BSA'),
  LegalTerm(term: 'Burden of Proof', category: 'Evidence', meaning: 'The obligation to prove a disputed fact. In civil cases on the plaintiff, in criminal on prosecution.', usage: 'The burden of proof lies on the prosecution to prove guilt beyond reasonable doubt.', section: 'Sec 104 BSA'),
  LegalTerm(term: 'Beyond Reasonable Doubt', category: 'Evidence', meaning: 'The standard of proof in criminal cases — the evidence must be so convincing that no reasonable doubt remains.', usage: 'The prosecution failed to prove the charge beyond reasonable doubt, resulting in acquittal.'),
  LegalTerm(term: 'Preponderance of Probability', category: 'Evidence', meaning: 'The standard of proof in civil cases — more likely than not.', usage: 'On preponderance of probability, the court found the plaintiff\'s version more credible.'),
  LegalTerm(term: 'Fundamental Rights', category: 'Constitutional', meaning: 'Basic rights guaranteed under Part III of the Constitution (Articles 12-35).', usage: 'The detention was challenged as violating the fundamental right to life under Article 21.', section: 'Part III Constitution'),
  LegalTerm(term: 'DPSP', category: 'Constitutional', meaning: 'Directive Principles of State Policy. Guidelines for the State in policy making, not enforceable by courts.', usage: 'DPSP under Article 39(b) directs the State to distribute material resources for the common good.', section: 'Part IV Constitution'),
  LegalTerm(term: 'Preamble', category: 'Constitutional', meaning: 'The introductory statement of the Constitution setting out its guiding purpose and philosophy.', usage: 'The Preamble declares India to be a Sovereign, Socialist, Secular, Democratic Republic.'),
  LegalTerm(term: 'Vested Right', category: 'Legal English', meaning: 'A right that has become fixed and cannot be taken away without due process.', usage: 'The employee\'s pension is a vested right; it cannot be taken away by changing service rules retrospectively.'),
  LegalTerm(term: 'Tort', category: 'Legal English', meaning: 'A civil wrong (other than breach of contract) causing loss, for which the remedy is damages.', usage: 'The plaintiff sued in tort for negligence after the defendant\'s careless driving caused the accident.'),
  LegalTerm(term: 'Damages', category: 'Legal English', meaning: 'Monetary compensation awarded by a court for loss or injury suffered.', usage: 'The court awarded ₹5,00,000 as damages for medical negligence by the hospital.'),
  LegalTerm(term: 'Indemnity', category: 'Legal English', meaning: 'A promise to compensate for any loss suffered by the other party.', usage: 'The guarantor agreed to indemnify the bank against any loss arising from the borrower\'s default.', section: 'Sec 124 Indian Contract Act'),
  LegalTerm(term: 'Arbitration', category: 'Legal English', meaning: 'A method of alternative dispute resolution where disputes are settled by an arbitrator instead of court.', usage: 'The contract contained an arbitration clause; the dispute was referred to a sole arbitrator.', section: 'Arbitration and Conciliation Act, 1996'),
  LegalTerm(term: 'Mediation', category: 'Legal English', meaning: 'A voluntary dispute resolution process where a neutral mediator helps parties reach a mutual settlement.', usage: 'The court referred the matrimonial dispute to mediation under Section 89 CPC.', section: 'Sec 89 CPC / Mediation Act, 2023'),
  LegalTerm(term: 'Compromise Decree', category: 'Legal English', meaning: 'A decree passed by consent of both parties based on a mutual settlement.', usage: 'Both parties settled the land dispute and a compromise decree was passed under Order 23 Rule 3 CPC.', section: 'Order 23 Rule 3 CPC'),
  LegalTerm(term: 'Interlocutory Order', category: 'Legal English', meaning: 'A temporary order made during the pendency of a case, not the final decision.', usage: 'The grant of interim injunction is an interlocutory order and may be modified at any time.'),
  LegalTerm(term: 'Mesne Profits', category: 'Property', meaning: 'Profits which a wrongful occupant has earned from property. Payable to the rightful owner.', usage: 'The court directed the defendant to pay mesne profits at ₹10,000/month for the period of wrongful occupation.', section: 'Sec 2(12) CPC'),
  LegalTerm(term: 'Garnishee Order', category: 'Legal English', meaning: 'A court order directing a third party (who owes money to the judgment debtor) to pay it to the decree holder.', usage: 'A garnishee order was issued against the bank to attach the judgment debtor\'s account.', section: 'Order 21 Rule 46 CPC'),
  LegalTerm(term: 'Nikah', category: 'Legal English', meaning: 'Islamic marriage contract. A solemn agreement between bride and groom with witnesses and mahr.', usage: 'The validity of nikah was disputed as the bride\'s consent was allegedly not freely given.'),
  LegalTerm(term: 'Mahr', category: 'Legal English', meaning: 'Dower in Muslim law. The obligatory gift (money or property) given by the husband to the wife at marriage.', usage: 'The wife filed a suit for recovery of unpaid mahr of ₹5,00,000 agreed at the time of nikah.'),
  LegalTerm(term: 'Iddat', category: 'Legal English', meaning: 'The waiting period a Muslim woman must observe after divorce or death of husband before remarrying.', usage: 'The husband is liable to maintain the wife during the iddat period of three menstrual cycles.'),
  LegalTerm(term: 'Talaq', category: 'Legal English', meaning: 'Divorce in Muslim law. The dissolution of marriage by the husband pronouncing divorce.', usage: 'Triple talaq in one sitting was declared unconstitutional by the Supreme Court in Shayara Bano (2017).'),
  LegalTerm(term: 'Khula', category: 'Legal English', meaning: 'Divorce initiated by the wife in Muslim law, usually with return of mahr to the husband.', usage: 'The wife obtained khula by mutual agreement, returning the mahr amount to the husband.'),
  LegalTerm(term: 'Wakf', category: 'Legal English', meaning: 'Permanent dedication of movable or immovable property by a Muslim for religious or charitable purposes.', usage: 'The property was registered as wakf and cannot be transferred as it is dedicated for public charity.', section: 'Wakf Act, 1995'),
  LegalTerm(term: 'Coparcener', category: 'Property', meaning: 'A person who shares equally in inheritance of an undivided Hindu ancestral estate. Post-2005 amendment includes daughters.', usage: 'The daughter claimed her right as a coparcener in the joint Hindu family property.', section: 'Sec 6 Hindu Succession Act'),
  LegalTerm(term: 'Karta', category: 'Property', meaning: 'The manager of a Hindu Undivided Family (HUF), usually the eldest male member.', usage: 'The Karta alienated ancestral property claiming legal necessity for the family.'),
  LegalTerm(term: 'Streedhan', category: 'Property', meaning: 'Property that belongs exclusively to a Hindu woman — gifts received before, during, or after marriage.', usage: 'The gold jewellery given at marriage is her streedhan and the husband has no right over it.'),
